-- ----------------------------
-- Table structure for edificios_escolares
-- ----------------------------
DROP TABLE IF EXISTS `edificios_escolares`;
CREATE TABLE `edificios_escolares`  (
  `cct` char(10) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL COMMENT 'campo de 10 caracteres en el cual se asigna la clave del centro de trabajo',
  `tipo_centro` char(2) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `desc_tipo_centro` varchar(100) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `turno` char(3) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL COMMENT 'campo de 3 caracteres en el cual se asigna la clave del turno',
  `desc_turno` varchar(50) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL COMMENT 'campo de 50 caracteres en el cual se describe el nombre del turno',
  `servicio` char(10) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL COMMENT 'campo de 2 caracteres en el que se asigna la clave del servicio',
  `desc_servicio` varchar(255) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL COMMENT 'campo de 2 caracteres en el que se describe el nombre del servicio',
  `sostenimiento` char(2) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL COMMENT 'campo de 2 caracteres en el cial se asigna la clave del sostenimiento',
  `desc_sostenimiento` varchar(255) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL COMMENT 'campo de 100 caracteres en el que se describe el nombre del sostenimiento',
  `nivel_educativo` char(2) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL COMMENT 'Identificador de 2 caracteres en el cual se asigna la clave del nivel educativo',
  `desc_nivel_educativo` varchar(50) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL COMMENT 'Campo de 50 caracteres en el cual se describe el nivel educativo',
  `subnivel_educativo` char(3) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL COMMENT 'Identificador de 2 caracteres en el cual se asigna la clave del subnivel educativo',
  `desc_subnivel_educativo` varchar(50) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL COMMENT 'Campo de 50 caracteres en el cual se describe el subnivel educativo',
  `nombre` varchar(255) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL COMMENT 'campo de 100 caracteres en el cual se describe el nombre asignado al centro de trabajo',
  `status` char(1) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL COMMENT 'Campo de 1 caracter en el cual se asigna la clave del estatus',
  `desc_status` varchar(20) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL COMMENT 'Campo de 20 caracter en el cual se describe el nombre del estatus',
  `modalidad` char(3) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `desc_modalidad` varchar(50) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `fecha_alta` datetime(0) NULL DEFAULT NULL COMMENT 'campo de 10 caracteres de tipo fecha en el cual se asigna la fecha en que realizo el movimiento de alta el centro de trabajo',
  `fecha_baja` datetime(0) NULL DEFAULT NULL COMMENT 'campo de 10 caracteres de tipo fecha en el cual se asigna la fecha en que realizo el movimiento de baja el centro de trabajo',
  `fecha_clausura` datetime(0) NULL DEFAULT NULL COMMENT 'campo de 10 caracteres de tipo fecha en el cual se asigna la fecha en que realizo el movimiento de clausura el centro de trabajo',
  `fecha_reapertura` datetime(0) NULL DEFAULT NULL COMMENT 'campo de 10 caracteres de tipo fecha en el cual se asigna la fecha en que realizo el movimiento de reapertura el centro de trabajo',
  `fecha_cambio` datetime(0) NULL DEFAULT NULL COMMENT 'campo de 10 caracteres de tipo fecha en el cual se asigna la fecha en que realizo el movimiento del centro de trabajo',
  `region` char(3) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `des_region` varchar(50) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL COMMENT 'Campo de 50 caracteres en el cual se describe el nombre de la region',
  `municipio` char(3) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `nombre_de_municipio` varchar(50) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL COMMENT 'Identificador de 50 caracteres en el cual se describe el nombre del municipio',
  `localidad` char(4) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `nombre_de_localidad` varchar(100) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL COMMENT 'campo de 100 caracteres en el cual se describe el nombre de la localidad',
  `categoria_poblacion` char(2) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL COMMENT 'campo de 1 caracter en el cual se asigna la clave del ambito',
  `desc_categoria_poblacion` varchar(30) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL COMMENT 'campo de 30 caracteres en el cual se describe el nombre del ambito',
  `cve_asentamiento` int(11) NULL DEFAULT NULL,
  `codigo_postal` char(5) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `asentamiento` varchar(100) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `cve_tipo_asentamiento` varchar(2) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `tipo_asentamiento` varchar(255) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `numero_exterior` varchar(50) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `numero_interior` varchar(5) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `latitud` decimal(10,7) NULL DEFAULT NULL,
  `longitud` decimal(10,7) NULL DEFAULT NULL,
  INDEX `idx_codigo_postal` (`codigo_postal`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = latin1 COLLATE = latin1_swedish_ci ROW_FORMAT = Dynamic;



